import { Suspense } from 'react'
import { notFound } from 'next/navigation'
import { getProduct, getRelatedProducts } from '@/lib/products'

type Params = Promise<{ slug: string }>
type SearchParams = Promise<{ currency?: string }>

// Not async: the shop frame prerenders into the static shell while the URL data
// (slug + currency) resolves inside the Suspense boundaries below.
export default function ProductPage({
  params,
  searchParams,
}: {
  params: Params
  searchParams: SearchParams
}) {
  return (
    <main>
      <p>Signal Shop collection</p>
      <Suspense fallback={<p>Loading product…</p>}>
        <ProductDetails params={params} searchParams={searchParams} />
      </Suspense>
      <section>
        <h2>Related products</h2>
        <Suspense fallback={<p>Loading related products…</p>}>
          <RelatedProducts params={params} />
        </Suspense>
      </section>
    </main>
  )
}

// Reads URL data, then passes the plain values to the cached data function.
async function ProductDetails({
  params,
  searchParams,
}: {
  params: Params
  searchParams: SearchParams
}) {
  const { slug } = await params
  const { currency = 'USD' } = await searchParams
  const product = await getProduct(slug, currency)
  if (!product) notFound()

  return (
    <>
      <h1>{product.name}</h1>
      <p>{product.price}</p>
    </>
  )
}

async function RelatedProducts({ params }: { params: Params }) {
  const { slug } = await params
  const related = await getRelatedProducts(slug)

  return (
    <>
      {related.map((item) => (
        <p key={item.slug}>{item.name}</p>
      ))}
    </>
  )
}

